// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testFuzz_property(uint256 initialMint, uint256 burnAmount) public {
        burnAmount = bound(burnAmount, 1, type(uint128).max);
        initialMint = bound(initialMint, burnAmount, type(uint128).max);

        vm.prank(c.owner());
        c.mintToken(c.owner(), initialMint);

        uint256 totalBefore = c.totalSupply();
        uint256 ownerBalBefore = c.balanceOf(c.owner());

        vm.prank(c.owner());
        c.burn(burnAmount);

        uint256 totalAfter = c.totalSupply();
        uint256 ownerBalAfter = c.balanceOf(c.owner());
        assertTrue(totalAfter == ownerBalAfter, "totalSupply must equal sum of all balances");
    }
}
